<style lang="scss" scoped>
@use '@/assets/scss/abstracts/colors' as c;

.loadingScene__spinner {
    fill: none;
    stroke: c.$loadingSpinner;
    stroke-width: 10;
    stroke-linecap: round;
    stroke-dasharray: 25 75;   // en kvart bue og et hul resten af vejen (pathLength er 100)
    animation: loadingSpin 1.2s linear infinite;

    // Roligere for dem, der har slået animationer ned på deres enhed
    @media (prefers-reduced-motion: reduce) {
        animation-duration: 4s;
    }
}

@keyframes loadingSpin {
    to {
        stroke-dashoffset: -100;   // buen flytter én hel omgang med uret
    }
}

.loadingScene__bubbleText {
    display: flex;
    flex-direction: column;
    justify-content: center;
    height: 100%;
    color: c.$secondary;
    font-size: 36px;    // i tegningens mål, så teksten vokser og skrumper med skærmen
    line-height: 1.6;
}
</style>
